import time


class Limiter:
    def __init__(self, per_minute):
        self.per_minute = per_minute
        self.hits = {}

    def allow(self, client):
        now = time.time()
        window = [t for t in self.hits.get(client, []) if now - t < 60]
        if len(window) >= self.per_minute:
            return False
        window.append(now)
        self.hits[client] = window
        return True
